-- =============================================================================
-- SCRIPT INSERT DỮ LIỆU SEED TỪ EXCEL & THƯ MỤC ẢNH VÀO DATABASE ENCHANTED_RENTAL
-- Được tạo tự động bởi generate_insert_sql.py
-- =============================================================================
USE [enchanted_rental];
GO
SET NOCOUNT ON;
GO

BEGIN TRANSACTION;
BEGIN TRY

    -- -------------------------------------------------------------------------
    -- 1. BẢNG [dbo].[Type]
    -- -------------------------------------------------------------------------
    SET IDENTITY_INSERT [dbo].[Type] ON;
    SET IDENTITY_INSERT [dbo].[Type] OFF;
    PRINT N'Inserted [Type] successfully.';

    -- -------------------------------------------------------------------------
    -- 2. BẢNG [dbo].[Category]
    -- -------------------------------------------------------------------------
    SET IDENTITY_INSERT [dbo].[Category] ON;
    SET IDENTITY_INSERT [dbo].[Category] OFF;
    PRINT N'Inserted [Category] successfully.';

    -- -------------------------------------------------------------------------
    -- 3. BẢNG [dbo].[Product]
    -- -------------------------------------------------------------------------
    SET IDENTITY_INSERT [dbo].[Product] ON;
    SET IDENTITY_INSERT [dbo].[Product] OFF;
    PRINT N'Inserted [Product] successfully.';

    -- -------------------------------------------------------------------------
    -- 4. BẢNG [dbo].[ProductItem]
    -- -------------------------------------------------------------------------
    SET IDENTITY_INSERT [dbo].[ProductItem] ON;
    SET IDENTITY_INSERT [dbo].[ProductItem] OFF;
    PRINT N'Inserted [ProductItem] successfully.';

    -- -------------------------------------------------------------------------
    -- 5. BẢNG [dbo].[ProductImage]
    -- -------------------------------------------------------------------------
    SET IDENTITY_INSERT [dbo].[ProductImage] ON;
    SET IDENTITY_INSERT [dbo].[ProductImage] OFF;
    PRINT N'Inserted [ProductImage] successfully.';

    -- -------------------------------------------------------------------------
    -- 6. CẬP NHẬT LẠI GIÁ TRỊ IDENTITY (RESEED)
    -- -------------------------------------------------------------------------
    DBCC CHECKIDENT ('[dbo].[Type]', RESEED, 2);
    DBCC CHECKIDENT ('[dbo].[Category]', RESEED, 17);
    DBCC CHECKIDENT ('[dbo].[Product]', RESEED, 2073);
    DBCC CHECKIDENT ('[dbo].[ProductItem]', RESEED, 2073);
    DBCC CHECKIDENT ('[dbo].[ProductImage]', RESEED, 918);

    COMMIT TRANSACTION;
    PRINT N'======================================================';
    PRINT N'TOÀN BỘ DỮ LIỆU ĐÃ ĐƯỢC INSERT THÀNH CÔNG VÀO DATABASE!';
    PRINT N'======================================================';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;
    PRINT N'CÓ LỖI XẢY RA TRONG QUÁ TRÌNH INSERT DỮ LIỆU: ' + ERROR_MESSAGE();
    THROW;
END CATCH;
GO